import { describe, expect, it } from 'vitest'
import {
  addCard,
  type Board,
  type Card,
  deleteCard,
  emptyBoard,
  isOverWip,
  isOverdue,
  isValidDate,
  loadBoard,
  matchesFilter,
  moveCard,
  moveCardToAdjacentColumn,
  moveCardWithinColumn,
  normalizeInput,
  parseBoard,
  saveBoard,
  STORAGE_KEY,
  todayString,
  updateCard,
} from './board'

const card = (id: string, extra: Partial<Card> = {}): Card => ({
