import { test } from '@playwright/test'

test('debug touch scroll', async ({ page }, info) => {
  test.skip(info.project.name !== 'mobile')
  await page.goto('/')
  await page.evaluate(() => {
    localStorage.setItem('personal-kanban.board.v1', JSON.stringify({ todo: ['A', 'B', 'C'].map((t) => ({ id: t, title: t, description: '', due: '', priority: 'low' })), doing: [], done: [] }))
    for (const t of ['pointerdown', 'pointermove', 'pointerup', 'pointercancel']) window.addEventListener(t, (e) => ((window as any).log ??= []).push(`${t} ${(e as PointerEvent).pointerType} ${Math.round((e as PointerEvent).clientY)} sy=${scrollY}`), true)
  })
  await page.reload()
  await page.evaluate(() => {
    for (const t of ['pointerdown', 'pointermove', 'pointerup', 'pointercancel']) window.addEventListener(t, (e) => ((window as any).log ??= []).push(`${t} ${(e as PointerEvent).pointerType} ${Math.round((e as PointerEvent).clientY)} sy=${Math.round(scrollY)} drag=${document.body.classList.contains('dragging')}`), true)
  })
  const grip = page.locator('li[data-card-id="A"] [data-grip]')
  const a = (await grip.boundingBox())!
  console.log('doing box', await page.locator('[data-column="doing"]').boundingBox(), 'scrollH', await page.evaluate(() => document.documentElement.scrollHeight))
  const cdp = await page.context().newCDPSession(page)
  const touch = (type: string, x: number, y: number) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: type === 'touchEnd' ? [] : [{ x, y }] })
  await touch('touchStart', a.x + 10, a.y + 10)
  for (let i = 1; i < 10; i++) await touch('touchMove', a.x + 10, a.y + 10 + i * 60)
  for (let i = 0; i < 20; i++) { await touch('touchMove', a.x + 10, 730); await page.waitForTimeout(30) }
  console.log('doing box after', await page.locator('[data-column="doing"]').boundingBox())
  await page.screenshot({ path: 'shots/debug.png' })
  await touch('touchEnd', 0, 0)
  console.log((await page.evaluate(() => (window as any).log)).join('\n'))
})

